/// Order management with status filter tabs.
class OrdersPageWidget extends StatefulWidget {
  const OrdersPageWidget({super.key});

  static String routeName = 'OrdersPage';
  static String routePath = '/orders';

  @override
  State<OrdersPageWidget> createState() => _OrdersPageWidgetState();
}

class _OrdersPageWidgetState extends State<OrdersPageWidget> {
  late OrdersPageModel _model;

  final scaffoldKey = GlobalKey<ScaffoldState>();

  @override
  void initState() {
    super.initState();
    _model = createModel(context, () => OrdersPageModel());

    // On page load action.
    SchedulerBinding.instance.addPostFrameCallback((_) async {
      // Phase 1 multi-tenancy pass: every tab below was unscoped and would
      // list orders across all orgs. Requires supabase/phase1_add_org_id.sql
      // to be run first (see that file's header).
      _model.allOut = await OrdersTable().queryRows(
        queryFn: (q) => OrgScope.read(q).order('created_at'),
      );
      _model.ordersList = _model.allOut!.toList().cast<OrdersRow>();
      safeSetState(() {});
      _model.pendingOut = await OrdersTable().queryRows(
        queryFn: (q) => OrgScope.read(q)
            .eqOrNull(
              'status',
              'pending',
            )
            .order('created_at'),
      );
      _model.pendingOrders = _model.pendingOut!.toList().cast<OrdersRow>();
      safeSetState(() {});
      _model.confirmedOut = await OrdersTable().queryRows(
        queryFn: (q) => OrgScope.read(q)
            .eqOrNull(
              'status',
              'confirmed',
            )
            .order('created_at'),
      );
      _model.confirmedOrders = _model.confirmedOut!.toList().cast<OrdersRow>();
      safeSetState(() {});
      _model.transitOut = await OrdersTable().queryRows(
        queryFn: (q) => OrgScope.read(q)
            .eqOrNull(
              'status',
              'transit',
            )
            .order('created_at'),
      );
      _model.transitOrders = _model.transitOut!.toList().cast<OrdersRow>();
      safeSetState(() {});
      _model.doneOut = await OrdersTable().queryRows(
        queryFn: (q) => OrgScope.read(q)
            .eqOrNull(
              'status',
              'delivered',
            )
            .order('created_at'),
      );
      _model.doneOrders = _model.doneOut!.toList().cast<OrdersRow>();
      safeSetState(() {});
      _model.cancelledOut = await OrdersTable().queryRows(
        queryFn: (q) => OrgScope.read(q)
            .eqOrNull(
              'status',
              'cancelled',
            )
            .order('created_at'),
      );
      _model.cancelledOrders = _model.cancelledOut!.toList().cast<OrdersRow>();
      safeSetState(() {});
    });

    WidgetsBinding.instance.addPostFrameCallback((_) => safeSetState(() {}));
  }

  @override
  void dispose() {
    _model.dispose();

    super.dispose();
  }

